```typescript
// Install pg package
npm install pg
```

### Code Example: PostgreSQL Connection

```typescript
import { Pool } from 'pg';

const pool = new Pool({
  user: 'aiko',
  host: 'localhost',
  database: 'ecommerce',
  password: 'password',
  port: 5432,
});

pool.query('CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY, name TEXT NOT NULL, price REAL NOT NULL)', (err, res) => {
  if (err) {
    console.error(err);
  } else {
    console.log('Table created successfully');
