```typescript
import React, { useState } from 'react';

interface FuncProps {
  name: string;
}

const MyFuncComponent: React.FC<FuncProps> = ({ name }) => {
  const [count, setCount] = useState(0);

  const increment = () => {
    setCount((prevCount) => prevCount + 1);
  };

  return (
    <div>
      <h1>{name}</h1>
      <button onClick={increment}>Increment</button>
      <p>Count: {count}</p>
    </div>
  );
};

export default MyFuncComponent;
```

## Higher-Order Component (HOC)

HOC is a pattern that takes a component and returns a new component. It's useful for reusing component logic without duplicating code.

```typescript
import React from 'react';

interface HocProps {
  children: React.ReactNode;
}

const withExtraProps = (Component: React.ComponentType<HocProps>) => {
  return (props: HocProps) => {
    return <Component {...props} extraProp="extraValue" />;
  };
};

const MyComponent = (props: HocProps) => {
  return <div>{props.children}</div>;
};

const EnhancedComponent = withExtraProps(MyComponent);

export default EnhancedComponent;
```

## Render Props

Render props are a pattern where you pass a function to a component as a prop. The function is then called to render the component's output.

```typescript
import React from 'react';

interface RenderPropsProps {
  onRender: () => React.ReactNode;
}

const RenderPropsComponent: React.FC<RenderPropsProps> = ({ onRender }) => {
  return <div>{onRender()}</div>;
};

const MyComponent = () => {
  return <h1>My Component</h1>;
};

const App = () => {
  return (
    <RenderPropsComponent onRender={MyComponent} />
  );
};

export default App;
```

## Context API

Context API is a way to pass data through the component tree without having to pass props down manually at every level.

```typescript
import React, { createContext, useContext } from 'react';

interface ThemeContextType {
  theme: string;
}

const ThemeContext = createContext<ThemeContextType>({
  theme: 'light',
});

const ThemedComponent = () => {
  const theme = useContext(ThemeContext);
  return <div>{theme}</div>;
};

const App = () => {
  return (
    <ThemeContext.Provider value={{ theme: 'dark' }}>
      <ThemedComponent />
    </ThemeContext.Provider>
  );
};

export default App;
```

## Hooks (useState, useEffect, etc.)

Hooks are functions that let you "hook into" React state and lifecycle features from function components.

```typescript
import React, { useState, useEffect } from 'react';

const MyHookComponent = () => {
  const [count, setCount] = useState(0);
  const [name, setName] = useState('');

  useEffect(() => {
    console.log(`Name changed to: ${name}`);
  }, [name]);

  return (
    <div>
      <input value={name} onChange={(e) => setName(e.target.value)} />
      <p>Count: {count}</p>
    </div>
  );
};

export default MyHookComponent;
```

## Comparison Table

| Design Pattern | Advantages | Disadvantages |
| --- | --- | --- |
| Class Component | Traditional, familiar | More verbose, less flexible |
| Function Component | Modern, concise | Limited state and lifecycle features |
| HOC | Reusability | Can lead to a complex component tree |
| Render Props | Flexibility | Can lead to a complex component tree |
| Context API | Global state management | Overuse can lead to a complex component tree |
| Hooks | Modern, concise | Limited features compared to class components |

## Actionable Takeaways

- Choose a design pattern based on your project requirements and team expertise.
- Use class components for complex state management and lifecycle features.
- Use function components and hooks for simple and modern code.
- Be cautious with HOC and render props to avoid a complex component tree.
- Use Context API for global state management but avoid overusing it.

By understanding and utilizing these design patterns, developers can create cleaner, more maintainable, and scalable React components in TypeScript.
