## 2. Metric Collection

### Core Metrics for AI Agent Systems

Essential metrics every autonomous agent system should collect:

| Metric | Description | Alert Threshold |
|--------|-------------|-----------------|
| **Task Success Rate** | % of tasks completing successfully | < 95% |
| **Task Latency P95/P99** | 95th/99th percentile execution time | > 5min / > 15min |
| **Error Rate** | Errors per minute | > 10/min |
| **Queue Depth** | Tasks waiting in todo state | > 100 |
| **Active Tasks** | Currently executing tasks | < 1 when queue > 0 |
| **Retry Rate** | Tasks requiring retries | > 30% |

### Implementation Pattern

```typescript
// metrics.ts — Metric collection and aggregation

interface TaskMetrics {
  total: number;
  success: number;
  failed: number;
  pending: number;
  avgLatencyMs: number;
  p95LatencyMs: number;
  p99LatencyMs: number;
}

interface SystemMetrics {
  timestamp: string;
  tasks: TaskMetrics;
  errors: {
    count: number;
    byType: Record<string, number>;
  };
  resources: {
    memoryUsageMB: number;
    cpuPercent: number;
  };
}

class MetricsCollector {
  private errors: Array<{ type: string; timestamp: number }> = [];
  private latencies: number[] = [];
  private taskResults: Array<{ success: boolean; latencyMs: number }> = [];

  recordTaskResult(success: boolean, latencyMs: number): void {
    this.taskResults.push({ success, latencyMs });
    this.latencies.push(latencyMs);

    // Keep only last 1000 samples
    if (this.latencies.length > 1000) {
      this.latencies = this.latencies.slice(-1000);
    }
    if (this.taskResults.length > 1000) {
      this.taskResults = this.taskResults.slice(-1000);
    }
  }

  recordError(errorType: string): void {
    this.errors.push({ type: errorType, timestamp: Date.now() });
    if (this.errors.length > 500) {
      this.errors = this.errors.slice(-500);
    }
  }

  calculateTaskMetrics(): TaskMetrics {
    if (this.taskResults.length === 0) {
      return { total: 0, success: 0, failed: 0, pending: 0, avgLatencyMs: 0, p95LatencyMs: 0, p99LatencyMs: 0 };
    }

    const sorted = [...this.latencies].sort((a, b) => a - b);
    const success = this.taskResults.filter(t => t.success).length;

    return {
      total: this.taskResults.length,
      success,
      failed: this.taskResults.length - success,
      pending: 0, // from DB
      avgLatencyMs: this.latencies.reduce((a, b) => a + b, 0) / this.latencies.length,
      p95LatencyMs: sorted[Math.floor(sorted.length * 0.95)] || 0,
      p99LatencyMs: sorted[Math.floor(sorted.length * 0.99)] || 0,
    };
  }

  calculateSystemMetrics(): SystemMetrics {
    const recentErrors = this.errors.filter(
      e => Date.now() - e.timestamp < 60000 // last minute
    );
    const errorByType = recentErrors.reduce((acc, e) => {
      acc[e.type] = (acc[e.type] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    return {
      timestamp: new Date().toISOString(),
      tasks: this.calculateTaskMetrics(),
      errors: {
        count: recentErrors.length,
        byType: errorByType,
      },
      resources: {
        memoryUsageMB: Math.round(process.memoryUsage().heapUsed / 1024 / 1024),
        cpuPercent: 0, // would use os.cpuUsage() in real impl
      },
    };
  }

  // Export for Prometheus / external monitoring
  toPrometheus(): string {
    const m = this.calculateSystemMetrics();
    let output = `# HELP task_total Total number of tasks processed
# TYPE task_total counter
task_total ${m.tasks.total}
# HELP task_success_total Total successful tasks
# TYPE task_success_total counter
task_success_total ${m.tasks.success}
# HELP task_failure_total Total failed tasks
# TYPE task_failure_total counter
task_failure_total ${m.tasks.failed}
# HELP task_latency_ms Task latency in milliseconds
# TYPE task_latency_ms summary
task_latency_ms {quantile="0.95"} ${m.tasks.p95LatencyMs}
task_latency_ms {.99"} ${quantile="0m.tasks.p99LatencyMs}
`;
    return output;
  }
}
```

