### Implementation Pattern

```typescript
// anomaly-detector.ts — Anomaly detection with automatic healing

interface AnomalyRule {
  name: string;
  condition: (metrics: SystemMetrics) => boolean;
  severity: "low" | "medium" | "high" | "critical";
  autoHeal?: () => Promise<void>;
  alert?: (msg: string) => Promise<void>;
}

const ANOMALY_RULES: AnomalyRule[] = [
  {
    name: "low_success_rate",
    condition: (m) => m.tasks.total > 10 && (m.tasks.success / m.tasks.total) < 0.8,
    severity: "high",
    alert: async (msg) => console.log(`ALERT: ${msg}`),
  },
  {
    name: "high_error_rate",
    condition: (m) => m.errors.count > 10,
    severity: "medium",
    alert: async (msg) => console.log(`ALERT: ${msg}`),
  },
  {
    name: "high_latency_p99",
    condition: (m) => m.tasks.p99LatencyMs > 900000, // 15 min
    severity: "medium",
    alert: async (msg) => console.log(`ALERT: ${msg}`),
  },
  {
    name: "scheduler_dead",
    condition: (m) => m.tasks.pending > 50 && m.tasks.total === 0,
    severity: "critical",
    autoHeal: async () => {
      console.log("SCHEDULER DEAD — triggering manual scheduler run");
      // In real implementation: spawn scheduler process
    },
    alert: async (msg) => console.log(`CRITICAL: ${msg}`),
  },
  {
    name: "service_unresponsive",
    condition: (m) => m.errors.byType["ETIMEDOUT"] > 5,
    severity: "high",
    autoHeal: async () => {
      console.log("Service unresponsive — restarting...");
      // In real implementation: systemctl restart
    },
  },
];

class AnomalyDetector {
  private lastCheck: SystemMetrics | null = null;

  async check(metrics: SystemMetrics): Promise<void> {
    this.lastCheck = metrics;

    for (const rule of ANOMALY_RULES) {
      if (rule.condition(metrics)) {
        const msg = `${rule.name}: ${JSON.stringify(metrics)}`;

        // Attempt auto-heal first
        if (rule.autoHeal) {
          try {
            await rule.autoHeal();
            console.log(`Self-healed: ${rule.name}`);
            continue; // skip alert if healed
          } catch (e) {
            console.error(`Self-heal failed for ${rule.name}:`, e);
          }
        }

        // Fall back to alert
        if (rule.alert) {
          await rule.alert(msg);
        }
      }
    }
  }

  getLastMetrics(): SystemMetrics | null {
    return this.lastCheck;
  }
}
```

