### Restart Policy Configuration

```typescript
// restart-policy.ts — Restart policy configuration

interface RestartPolicy {
  serviceName: string;
  maxRetries: number;
  windowMs: number;           // Time window for counting failures
  backoffMs: number;         // Initial backoff
  maxBackoffMs: number;      // Max backoff
  resetAfterMs: number;      // Reset failure count after this time
  critical: boolean;        // If true, alerts escalate
}

const RESTART_POLICIES: RestartPolicy[] = [
  {
    serviceName: "cursor-proxy",
    maxRetries: 3,
    windowMs: 15 * 60 * 1000,  // 15 minutes
    backoffMs: 10 * 1000,       // 10 seconds
    maxBackoffMs: 300 * 1000,   // 5 minutes
    resetAfterMs: 30 * 60 * 1000, // 30 minutes
    critical: true,
  },
  {
    serviceName: "openclaw-gateway",
    maxRetries: 5,
    windowMs: 30 * 60 * 1000,
    backoffMs: 10 * 1000,
    maxBackoffMs: 600 * 1000,
    resetAfterMs: 60 * 60 * 1000,
    critical: true,
  },
  {
    serviceName: "opencode-proxy",
    maxRetries: 2,
    windowMs: 10 * 60 * 1000,
    backoffMs: 30 * 1000,
    maxBackoffMs: 60 * 1000,
    resetAfterMs: 15 * 60 * 1000,
    critical: false,
  },
];

class RestartPolicyEngine {
  private failureCount: Map<string, number> = new Map();
  private firstFailureTime: Map<string, number> = new Map();
  private lastRestartTime: Map<string, number> = new Map();

  recordFailure(serviceName: string): { shouldRestart: boolean; backoffMs: number } {
    const policy = RESTART_POLICIES.find(p => p.serviceName === serviceName);
    if (!policy) return { shouldRestart: false, backoffMs: 0 };

    const now = Date.now();

    // Reset if outside window
    const firstFailure = this.firstFailureTime.get(serviceName);
    if (!firstFailure || now - firstFailure > policy.windowMs) {
      this.failureCount.set(serviceName, 1);
      this.firstFailureTime.set(serviceName, now);
      return { shouldRestart: true, backoffMs: policy.backoffMs };
    }

    // Increment failure count
    const count = (this.failureCount.get(serviceName) || 0) + 1;
    this.failureCount.set(serviceName, count);

    // Check if exceeded max retries
    if (count > policy.maxRetries) {
      return { shouldRestart: false, backoffMs: 0 }; // Too many failures
    }

    // Calculate backoff
    const backoffMs = Math.min(
      policy.backoffMs * Math.pow(2, count - 1),
      policy.maxBackoffMs
    );

    return { shouldRestart: true, backoffMs };
  }

  recordSuccess(serviceName: string): void {
    const policy = RESTART_POLICIES.find(p => p.serviceName === serviceName);
    if (!policy) return;

    // Reset after successful operation
    const lastSuccess = this.lastRestartTime.get(serviceName) || 0;
    if (Date.now() - lastSuccess > policy.resetAfterMs) {
      this.failureCount.set(serviceName, 0);
      this.firstFailureTime.delete(serviceName);
    }
  }

  getFailureCount(serviceName: string): number {
    return this.failureCount.get(serviceName) || 0;
  }
}
```

