## 5. Log Structured Analysis

### JSON Logging Pattern

```typescript
// logger.ts — Structured JSON logging

type LogLevel = "DEBUG" | "INFO" | "WARN" | "ERROR" | "CRITICAL";

interface LogEntry {
  timestamp: string;
  level: LogLevel;
  service: string;
  message: string;
  context?: Record<string, unknown>;
  error?: {
    name: string;
    message: string;
    stack?: string;
  };
  metrics?: Record<string, number>;
}

class StructuredLogger {
  private serviceName: string;

  constructor(serviceName: string) {
    this.serviceName = serviceName;
  }

  log(level: LogLevel, message: string, context?: Record<string, unknown>): void {
    const entry: LogEntry = {
      timestamp: new Date().toISOString(),
      level,
      service: this.serviceName,
      message,
      context,
    };

    // Write as JSON line
    console.log(JSON.stringify(entry));

    // In production: write to file / send to log aggregator
  }

  info(message: string, context?: Record<string, unknown>): void {
    this.log("INFO", message, context);
  }

  warn(message: string, context?: Record<string, unknown>): void {
    this.log("WARN", message, context);
  }

  error(message: string, error?: Error, context?: Record<string, unknown>): void {
    this.log("ERROR", message, {
      ...context,
      error: error ? {
        name: error.name,
        message: error.message,
        stack: error.stack,
      } : undefined,
    });
  }

  critical(message: string, error?: Error, context?: Record<string, unknown>): void {
    this.log("CRITICAL", message, {
      ...context,
      error: error ? {
        name: error.name,
        message: error.message,
        stack: error.stack,
      } : undefined,
    });
  }
}

// Usage
const logger = new StructuredLogger("scheduler");
logger.info("task_started", { taskId: "TASK-001", type: "blog" });
logger.error("task_failed", new Error("API rate limited"), { taskId: "TASK-001", retryCount: 2 });
```

### Error Classification

```typescript
// error-classifier.ts — Classify errors for appropriate response

type ErrorCategory = 
  | "transient"      // Temporary, retry may work
  | "resource"       // Resource exhaustion (memory, disk)
  | "config"         // Misconfiguration
  | "dependency"     // External service down
  | "logic"          // Bug in code
  | "rate_limit"     // API rate limit hit
  | "auth"           // Authentication/authorization failure
  | "unknown";

interface Classification {
  category: ErrorCategory;
  retryable: boolean;
  autoHealAction?: string;
  alertSeverity: "none" | "low" | "medium" | "high" | "critical";
}

const ERROR_PATTERNS: Array<{ pattern: RegExp; classification: Omit<Classification, "category"> }> = [
  { pattern: /ETIMEDOUT|ECONNRESET|ECONNREFUSED/, classification: { retryable: true, autoHealAction: "retry", alertSeverity: "low" } },
  { pattern: /rate.limit|429/, classification: { retryable: true, autoHealAction: "backoff", alertSeverity: "medium" } },
  { pattern: /OutOfMemoryError|ENOMEM/, classification: { retryable: false, autoHealAction: "restart", alertSeverity: "critical" } },
  { pattern: /EACCES|ENOENT.*config/, classification: { retryable: false, alertSeverity: "high" } },
  { pattern: /401|403.*auth|unauthorized/, classification: { retryable: false, alertSeverity: "high" } },
  { pattern: /validation.*failed|invalid.*input/, classification: { retryable: false, alertSeverity: "medium" } },
];

function classifyError(error: Error | string): Classification {
  const errorStr = error instanceof Error ? error.message : error;

  for (const { pattern, classification } of ERROR_PATTERNS) {
    if (pattern.test(errorStr)) {
      return { ...classification, category: "transient" }; // Simplified
    }
  }

  return {
    category: "unknown",
    retryable: false,
    alertSeverity: "medium",
  };
}

// Log aggregation query example (for analysis):
// jq 'select(.level == "ERROR") | .context.error.message' logs.json | sort | uniq -c | sort -rn
```

