## 6. OpenClaw Implementation: Real-World Case Study

### Architecture Overview

OpenClaw runs as an autonomous agent system with three core services:

1. **cursor-proxy** (:5588) — Task execution engine
2. **openclaw-gateway** (:18789) — API gateway / coordinator  
3. **scheduler** (cron-driven) — Task queue management

The watchdog service patrols all three services every 3 minutes, collecting metrics and triggering auto-recovery when needed.

### Watchdog Implementation

Here's the core watchdog logic from `services/watchdog.ts`:

```typescript
// Key sections from services/watchdog.ts

// Service configuration
const SERVICES = [
  {
    name: "cursor-proxy",
    unit: "cursor-proxy.service",
    healthUrl: "http://127.0.0.1:5588/health",
    statsUrl: "http://127.0.0.1:5588/stats",
    critical: true,
  },
  {
    name: "openclaw-gateway",
    unit: "openclaw-gateway.service",
    healthUrl: "http://127.0.0.1:18789/health",
    critical: true,
  },
];

// Health check with timeout
async function checkHealth(url: string, timeoutMs = 5000): Promise<{
  ok: boolean;
  status?: number;
  data?: any;
  error?: string;
}> {
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    const res = await fetch(url, { signal: controller.signal });
    clearTimeout(timer);
    if (!res.ok) return { ok: false, status: res.status, error: `HTTP ${res.status}` };
    const text = await res.text();
    try { return { ok: true, status: res.status, data: JSON.parse(text) }; } 
    catch { return { ok: true, status: res.status }; }
  } catch (e: any) {
    return { ok: false, error: e.message?.includes("abort") ? "timeout" : e.message };
  }
}

// Service restart via systemctl
async function restartService(unit: string): Promise<boolean> {
  try {
    const result = await $`systemctl --user restart ${unit}`.quiet();
    return result.exitCode === 0;
  } catch {
    return false;
  }
}

// Main patrol loop
async function patrol(): Promise<{ allHealthy: boolean; results: any[] }> {
  const state = loadState();
  state.totalChecks = (state.totalChecks || 0) + 1;

  const results: any[] = [];
  let allHealthy = true;

  for (const svc of SERVICES) {
    const health = await checkHealth(svc.healthUrl);
    const active = await isServiceActive(svc.unit);

    if (health.ok && active) {
      // Healthy: reset failure counter
      state.consecutiveFails[svc.name] = 0;
      log("OK", `${svc.name}: healthy (active)`);
      results.push({ name: svc.name, status: "healthy" });
    } else {
      // Unhealthy: increment failure counter
      allHealthy = false;
      const fails = (state.consecutiveFails[svc.name] || 0) + 1;
      state.consecutiveFails[svc.name] = fails;

      log("WARN", `${svc.name}: UNHEALTHY (active=${active}, health=${health.error || "fail"}, consecutive=${fails})`);

      // Auto-recovery: restart after 2+ consecutive failures
      if (fails >= 2 && svc.critical) {
        log("ACTION", `${svc.name}: restarting (consecutive fails: ${fails})`);
        const ok = await restartService(svc.unit);
        state.totalRestarts = (state.totalRestarts || 0) + 1;

        if (!state.restarts[svc.name]) state.restarts[svc.name] = [];
        state.restarts[svc.name].push({ at: new Date().toISOString(), success: ok });

        // Keep only last 20 restart records
        if (state.restarts[svc.name].length > 20) {
          state.restarts[svc.name] = state.restarts[svc.name].slice(-20);
        }

        if (ok) {
          // Wait and verify recovery
          await Bun.sleep(10000);
          const recheck = await checkHealth(svc.healthUrl);
          if (recheck.ok) {
            log("OK", `${svc.name}: recovered after restart`);
            state.consecutiveFails[svc.name] = 0;
          } else {
            log("ERROR", `${svc.name}: still unhealthy after restart!`);
          }
        } else {
          log("ERROR", `${svc.name}: restart FAILED`);
        }
      }

      results.push({ name: svc.name, status: "unhealthy", error: health.error, fails });
    }
  }

  saveState(state);
  return { allHealthy, results };
}
```

### Scheduler Liveness Check

The watchdog also monitors the scheduler for signs of death:

```typescript
// Check if scheduler is alive by querying task activity
async function checkSchedulerAlive() {
  const dbPath = `${process.env.HOME}/.openclaw/data/superpowers.db`;
  if (!existsSync(dbPath)) return;

  const db = new Database(dbPath, { readonly: true });

  const recent = db.prepare(`
    SELECT
      (SELECT COUNT(*) FROM tasks WHERE completed_at > datetime('now', '-10 minutes')) as done_10m,
      (SELECT COUNT(*) FROM tasks WHERE created_at > datetime('now', '-10 minutes')) as created_10m,
      (SELECT COUNT(*) FROM tasks WHERE status = 'todo') as todo_count
  `).get() as any;

  if (recent.done_10m === 0 && recent.created_10m === 0 && recent.todo_count > 0) {
    log("WARN", `Scheduler may be dead: 0 completions, 0 creates in 10min, ${recent.todo_count} todo waiting`);

    // Check if cron lock is free (scheduler not running)
    const lockCheck = await $`flock -n /tmp/scheduler.lock echo unlocked 2>&1`.quiet().nothrow();
    const lockFree = lockCheck.stdout.toString().includes("unlocked");

    if (lockFree) {
      // Manually trigger scheduler
      log("ACTION", "Scheduler lock is free — manually triggering scheduler");
      await $`bun run /home/zlj/code/ai-agent-ops/services/scheduler.ts >> /home/zlj/.openclaw/logs/scheduler.log 2>&1 &`.quiet().nothrow();
    }
  }
}
```

### CEO Anti-Idle Detection

OpenClaw detects when the CEO agent becomes idle and triggers recovery:

```typescript
// Detect CEO idle state and auto-recover
async function checkCeoActivity() {
  const recent = db.prepare(`
    SELECT COUNT(*) as cnt FROM tasks
    WHERE status = 'done' AND completed_at > datetime('now', '-15 minutes')
  `).get() as any;

  const doing = db.prepare(`SELECT COUNT(*) as cnt FROM tasks WHERE status = 'doing'`).get() as any;
  const todo = db.prepare(`SELECT COUNT(*) as cnt FROM tasks WHERE status = 'todo'`).get() as any;

  if (recent.cnt === 0 && doing.cnt === 0 && todo.cnt > 0) {
    // No completions in 15min, nothing in progress, but tasks available
    log("WARN", `CEO idle detected: 0 completions in 15min, ${todo.cnt} todo available, 0 doing`);

    // Restart gateway to trigger fresh heartbeat
    log("ACTION", "Restarting openclaw-gateway to wake up CEO...");
    await restartService("openclaw-gateway.service");

    // Rotate CEO session to clear idle patterns
    rotateCeoSession();
  }
}
```

### Daemon Loop

```typescript
// Main daemon loop runs every 3 minutes
if (args.includes("--daemon")) {
  log("INFO", `watchdog daemon started (interval: ${INTERVAL_MS / 1000}s)`);
  let checkCount = 0;

  const tick = async () => {
    checkCount++;
    await patrol();

    // Every 3 checks (~9 min): scheduler liveness + session cleanup
    if (checkCount % 3 === 0) {
      await checkSchedulerAlive();
      await runSessionCleanup();
    }

    // Every 20 checks (~1 hour): log rotation
    if (checkCount % 20 === 0) rotateLog();

    // Every 160 checks (~8 hours): growth analysis
    if (checkCount % 160 === 0) {
      await triggerGrowthAnalysis();
      await checkSelfDriveHealth();
    }
  };

  await tick();
  setInterval(tick, INTERVAL_MS);
}
