## SQLite as Agent Memory Store

SQLite provides an excellent foundation for agent memory storage. Its embedded nature, ACID compliance, and JSON support make it well-suited for the diverse data types required by agent memory systems.

### Schema Design

The following schema implements all four memory types with appropriate indexing for common query patterns.

```sql
-- Short-term Memory: Conversation Context
CREATE TABLE conversation_sessions (
    id TEXT PRIMARY KEY,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    metadata JSON
);

CREATE TABLE conversation_messages (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL REFERENCES conversation_sessions(id),
    role TEXT NOT NULL CHECK(role IN ('user', 'assistant', 'system')),
    content TEXT NOT NULL,
    token_count INTEGER NOT NULL,
    timestamp INTEGER NOT NULL,
    metadata JSON
);

CREATE INDEX idx_messages_session_time 
    ON conversation_messages(session_id, timestamp DESC);

CREATE INDEX idx_messages_token_count 
    ON conversation_messages(session_id, token_count);

-- Episodic Memory: Task Episodes
CREATE TABLE task_episodes (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL,
    task_type TEXT NOT NULL,
    input JSON NOT NULL,
    actions JSON NOT NULL,
    outcome JSON NOT NULL,
    metadata JSON NOT NULL,
    success INTEGER NOT NULL,
    duration_ms INTEGER NOT NULL,
    tokens_used INTEGER NOT NULL,
    created_at INTEGER NOT NULL
);

CREATE INDEX idx_episodes_task_type ON task_episodes(task_type);
CREATE INDEX idx_episodes_success ON task_episodes(task_type, success);
CREATE INDEX idx_episodes_created ON task_episodes(created_at DESC);

CREATE TABLE episode_analysis (
    id TEXT PRIMARY KEY,
    episode_id TEXT NOT NULL REFERENCES task_episodes(id),
    analysis_type TEXT NOT NULL,
    content TEXT NOT NULL,
    confidence REAL NOT NULL,
    created_at INTEGER NOT NULL
);

-- Semantic Memory: Knowledge Base
CREATE TABLE knowledge_entries (
    id TEXT PRIMARY KEY,
    content TEXT NOT NULL,
    embedding BLOB NOT NULL,
    metadata JSON NOT NULL,
    category TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);

CREATE INDEX idx_knowledge_category ON knowledge_entries(category);
CREATE INDEX idx_knowledge_created ON knowledge_entries(created_at DESC);

-- Procedural Memory: Templates and Configurations
CREATE TABLE prompt_templates (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    description TEXT,
    template TEXT NOT NULL,
    parameters JSON NOT NULL,
    variables JSON NOT NULL,
    version INTEGER NOT NULL DEFAULT 1,
    success_rate REAL NOT NULL DEFAULT 0,
    usage_count INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);

CREATE INDEX idx_templates_name ON prompt_templates(name);
CREATE INDEX idx_templates_success ON prompt_templates(success_rate DESC);

CREATE TABLE tool_configurations (
    id TEXT PRIMARY KEY,
    tool_name TEXT NOT NULL UNIQUE,
    description TEXT,
    parameters JSON NOT NULL,
    retry_config JSON NOT NULL,
    timeout_ms INTEGER NOT NULL DEFAULT 30000,
    version INTEGER NOT NULL DEFAULT 1,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);

CREATE TABLE workflow_patterns (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    description TEXT,
    steps JSON NOT NULL,
    success_rate REAL NOT NULL DEFAULT 0,
    avg_duration_ms INTEGER NOT NULL DEFAULT 0,
    usage_count INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
);

-- Memory Management
CREATE TABLE memory_sync_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    memory_type TEXT NOT NULL,
    operation TEXT NOT NULL,
    record_id TEXT NOT NULL,
    synced_at INTEGER NOT NULL
);

CREATE INDEX idx_sync_log_type ON memory_sync_log(memory_type, synced_at);
```

### Query Patterns

#### Short-term Memory Queries

```sql
-- Get recent conversation context within token limit
WITH ranked_messages AS (
    SELECT 
        id, role, content, token_count, timestamp,
        SUM(token_count) OVER (
            PARTITION BY session_id 
            ORDER BY timestamp DESC
        ) as cumulative_tokens
    FROM conversation_messages
    WHERE session_id = ?
)
SELECT id, role, content, timestamp
FROM ranked_messages
WHERE cumulative_tokens <= ?
ORDER BY timestamp ASC;

-- Get last N messages from a session
SELECT * FROM conversation_messages
WHERE session_id = ?
ORDER BY timestamp DESC
LIMIT ?;

-- Summarize session token usage
SELECT 
    session_id,
    COUNT(*) as message_count,
    SUM(token_count) as total_tokens,
    MAX(timestamp) as last_activity
FROM conversation_messages
WHERE session_id = ?
GROUP BY session_id;
```

#### Episodic Memory Queries

```sql
-- Find similar successful episodes
SELECT * FROM task_episodes
WHERE task_type = ?
    AND success = 1
    AND created_at > ?
ORDER BY created_at DESC
LIMIT 10;

-- Analyze failure patterns for a task type
SELECT 
    json_extract(outcome, '$.errorType') as error_type,
    COUNT(*) as count,
    AVG(duration_ms) as avg_duration
FROM task_episodes
WHERE task_type = ? 
    AND success = 0
GROUP BY error_type
ORDER BY count DESC;

-- Get success rate over time
SELECT 
    date(created_at/1000, 'unixepoch') as day,
    COUNT(*) as total,
    SUM(success) as successes,
    CAST(SUM(success) AS REAL) / COUNT(*) as rate
FROM task_episodes
WHERE task_type = ?
    AND created_at > ?
GROUP BY day
ORDER BY day DESC;
```

#### Semantic Memory Queries

```sql
-- Vector similarity search (using extension or application-side computation)
SELECT 
    id, content, metadata,
    distance(embedding, ?) as dist
FROM knowledge_entries
WHERE category = ?
ORDER BY dist
LIMIT ?;

-- Get recent knowledge by category
SELECT * FROM knowledge_entries
WHERE category = ?
ORDER BY created_at DESC
LIMIT ?;

-- Search with metadata filters
SELECT * FROM knowledge_entries
WHERE 
    json_extract(metadata, '$.confidence') >= ?
    AND (
        json_extract(metadata, '$.tags') LIKE ? 
        OR content LIKE ?
    )
ORDER BY created_at DESC
LIMIT ?;
```

#### Procedural Memory Queries

```sql
-- Get most successful templates for a task
SELECT * FROM prompt_templates
WHERE name LIKE ?
ORDER BY success_rate DESC, usage_count DESC
LIMIT ?;

-- Get tool configuration
SELECT * FROM tool_configurations
WHERE tool_name = ?;

-- Get most used workflow patterns
SELECT * FROM workflow_patterns
ORDER BY usage_count DESC
LIMIT ?;

-- Get recently updated configurations
SELECT * FROM prompt_templates
ORDER BY updated_at DESC
LIMIT ?;
```

## OpenClaw's Memory Tables: A Production Case Study

OpenClaw, an open-source agent framework, implements a comprehensive memory system that serves as an excellent reference for production deployments. Its approach combines the four memory types into a cohesive architecture.

### OpenClaw Schema Overview

OpenClaw uses SQLite with the following core tables:

```sql
-- Core memory tables
CREATE TABLE memories (
    id TEXT PRIMARY KEY,
    memory_type TEXT NOT NULL,
    content TEXT NOT NULL,
    embedding BLOB,
    metadata JSON,
    importance REAL DEFAULT 0.5,
    access_count INTEGER DEFAULT 0,
    last_accessed INTEGER,
    created_at INTEGER,
    updated_at INTEGER
);

CREATE TABLE memory_relations (
    id TEXT PRIMARY KEY,
    source_id TEXT REFERENCES memories(id),
    target_id TEXT REFERENCES memories(id),
    relation_type TEXT,
    weight REAL DEFAULT 1.0
);

CREATE TABLE context_windows (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL,
    memories JSON NOT NULL,
    token_count INTEGER NOT NULL,
    created_at INTEGER
);

CREATE TABLE learning_records (
    id TEXT PRIMARY KEY,
    memory_id TEXT REFERENCES memories(id),
    feedback TEXT,
    improvement JSON,
    created_at INTEGER
);
```

### Key Design Patterns from OpenClaw

#### 1. Unified Memory Table with Type Discrimination

OpenClaw uses a single `memories` table with a `memory_type` column, allowing flexible storage while maintaining query efficiency through proper indexing.

```sql
SELECT * FROM memories 
WHERE memory_type = 'episodic' 
    AND updated_at > ?
ORDER BY importance DESC;
```

#### 2. Memory Relations for Knowledge Graph

The `memory_relations` table enables building knowledge graphs from stored memories, supporting complex reasoning about relationships between concepts, episodes, and procedures.

```sql
-- Find related memories
SELECT m.* FROM memories m
JOIN memory_relations mr ON m.id = mr.target_id
WHERE mr.source_id = ?
ORDER BY mr.weight DESC;
```

#### 3. Importance Scoring

Each memory has an importance score that affects retention and retrieval priority:

```sql
-- Automatic importance adjustment based on access patterns
UPDATE memories 
SET 
    importance = importance * 0.95 + (access_count * 0.05),
    last_accessed = ?
WHERE id = ?;
```

#### 4. Context Window Management

OpenClaw implements sliding windows at the database level:

```sql
-- Get context within token limit
WITH windowed AS (
    SELECT 
        id, content, token_count,
        SUM(token_count) OVER (ORDER BY created_at DESC) as running_total
    FROM context_windows
    WHERE session_id = ?
)
SELECT * FROM windowed 
WHERE running_total <= ?
ORDER BY created_at DESC;
```

### Integration Patterns

#### Hybrid Retrieval

OpenClaw combines keyword and semantic search:

```typescript
async function hybridSearch(query: string, options: SearchOptions) {
  // 1. Get keyword matches
  const keywordResults = await db.query(
    `SELECT * FROM memories 
     WHERE content LIKE ? 
     ORDER BY importance DESC 
     LIMIT ?`,
    [`%${query}%`, options.limit]
  );

  // 2. Get semantic matches
  const queryEmbedding = await embeddingService.embed(query);
  const semanticResults = await vectorSearch(queryEmbedding, options);

  // 3. Merge and rerank
  return rerankResults(keywordResults, semanticResults, query);
}
```

#### Memory Consolidation

Periodic consolidation moves episodic memories into semantic knowledge:

```typescript
async function consolidateMemories(sessionId: string) {
  // Get recent episodic memories
  const episodes = await db.query(
    `SELECT * FROM memories 
     WHERE memory_type = 'episodic' 
     AND created_at > ?`,
    [Date.now() - 24 * 60 * 60 * 1000]
  );

  // Extract knowledge and create semantic memories
  for (const episode of episodes) {
    const extractedKnowledge = await extractKnowledge(episode);
    if (extractedKnowledge) {
      await storeSemanticMemory(extractedKnowledge);
    }
  }

  // Archive or delete processed episodic memories
  await db.execute(
    `DELETE FROM memories WHERE id = ?`,
    [episodes.map(e => e.id)]
  );
}
```

## Memory System Implementation Recommendations

### Tiered Storage Strategy

Implement memory with tiered storage based on access patterns and importance:

| Tier | Storage | Retention | Access Pattern |
|------|---------|-----------|----------------|
| Hot | In-memory | Seconds to minutes | Every request |
| Warm | SQLite | Hours to days | Frequent queries |
| Cold | Archive | Weeks to months | Rare queries |

### Memory Lifecycle Management

```typescript
