## 1. Retry Strategies

### 1.1 Exponential Backoff with Jitter

Prevents thundering herd problems when services recover.

```typescript
interface RetryConfig {
  maxAttempts: number;
  baseDelayMs: number;
  maxDelayMs: number;
  jitterFactor: number;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  baseDelayMs: 1000,
  maxDelayMs: 30000,
  jitterFactor: 0.3,
};

function calculateDelay(attempt: number, config: RetryConfig): number {
  const exponentialDelay = config.baseDelayMs * Math.pow(2, attempt - 1);
  const cappedDelay = Math.min(exponentialDelay, config.maxDelayMs);
  const jitter = cappedDelay * config.jitterFactor * (Math.random() - 0.5);
  return Math.max(0, cappedDelay + jitter);
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// From OpenClaw scheduler/index.ts:155-159
// Real-world: Retry failed tasks with tiered backoff (1min, 5min, 15min)
const BACKOFF_MINS = [1, 5, 15];

export async function withRetry<T>(
  operation: () => Promise<T>,
  config: Partial<RetryConfig> = {},
  operationName: string = 'operation'
): Promise<T> {
  const fullConfig = { ...DEFAULT_RETRY_CONFIG, ...config };

  for (let attempt = 1; attempt <= fullConfig.maxAttempts; attempt++) {
    try {
      return await operation();
    } catch (error) {
      const isLastAttempt = attempt === fullConfig.maxAttempts;

      if (isLastAttempt) {
        throw new Error(
          `${operationName} failed after ${attempt} attempt(s): ${
            error instanceof Error ? error.message : String(error)
          }`
        );
      }

      const delay = calculateDelay(attempt, fullConfig);
      console.log(`[retry] Attempt ${attempt} failed, waiting ${Math.round(delay)}ms...`);
      await sleep(delay);
    }
  }

  throw new Error('Unreachable: retry loop should have returned or thrown');
}
```

### 1.2 Circuit Breaker Pattern

Prevents cascading failures by stopping calls to unhealthy services.

```typescript
type CircuitState = 'closed' | 'open' | 'half-open';

interface CircuitBreakerConfig {
  failureThreshold: number;
  resetTimeoutMs: number;
  halfOpenMaxCalls: number;
}

const DEFAULT_CIRCUIT_CONFIG: CircuitBreakerConfig = {
  failureThreshold: 5,
  resetTimeoutMs: 30000,
  halfOpenMaxCalls: 3,
};

export class CircuitBreaker {
  private state: CircuitState = 'closed';
  private failureCount = 0;
  private successCount = 0;
  private lastFailureTime?: number;
  private halfOpenCalls = 0;

  constructor(
    private readonly config: Partial<CircuitBreakerConfig> = {},
    private readonly name: string = 'circuit'
  ) {
    this.config = { ...DEFAULT_CIRCUIT_CONFIG, ...config };
  }

  async execute<T>(operation: () => Promise<T>): Promise<T> {
    if (this.state === 'open') {
      if (this.shouldAttemptReset()) {
        this.state = 'half-open';
        this.halfOpenCalls = 0;
        this.successCount = 0;
      } else {
        throw new Error(
          `Circuit breaker '${this.name}' is open. Service temporarily unavailable.`
        );
      }
    }

    if (this.state === 'half-open' && 
        this.halfOpenCalls >= (this.config.halfOpenMaxCalls ?? 3)) {
      throw new Error(`Circuit breaker '${this.name}' half-open call limit reached`);
    }

    if (this.state === 'half-open') {
      this.halfOpenCalls++;
    }

    try {
      const result = await operation();
      this.onSuccess();
      return result;
    } catch (error) {
      this.onFailure();
      throw error;
    }
  }

  private shouldAttemptReset(): boolean {
    if (!this.lastFailureTime) return true;
    return Date.now() - this.lastFailureTime >= (this.config.resetTimeoutMs ?? 30000);
  }

  private onSuccess(): void {
    this.failureCount = 0;

    if (this.state === 'half-open') {
      this.successCount++;
      if (this.successCount >= (this.config.halfOpenMaxCalls ?? 3)) {
        this.state = 'closed';
        this.successCount = 0;
        this.halfOpenCalls = 0;
        console.log(`[circuit] ${this.name} closed - service recovered`);
      }
    }
  }

  private onFailure(): void {
    this.failureCount++;
    this.lastFailureTime = Date.now();

    if (this.state === 'half-open') {
      this.state = 'open';
      console.log(`[circuit] ${this.name} reopened - recovery failed`);
    } else if (this.failureCount >= (this.config.failureThreshold ?? 5)) {
      this.state = 'open';
      console.log(`[circuit] ${this.name} opened - failure threshold reached`);
    }
  }

  getState(): CircuitState {
    return this.state;
  }
}
```

### 1.3 Tiered Retry from OpenClaw

