// From OpenClaw scheduler/index.ts:151-161
// Retry failed tasks with exponential backoff based on retry count
async function retryFailedTasks(db: Database): Promise<void> {
  const failed = db.prepare(`
    SELECT id, title, retry_count 
    FROM tasks 
    WHERE status = 'failed' 
      AND retry_count < 3 
      AND completed_at > datetime('now', '-2 hours')
    ORDER BY retry_count ASC 
    LIMIT 3
  `).all() as any[];

  if (failed.length > 0) {
    // Backoff minutes: 1st retry = 1min, 2nd = 5min, 3rd = 15min
    const BACKOFF_MINS = [1, 5, 15];

    const readyToRetry = failed.filter((t) => {
      const backoffMinutes = BACKOFF_MINS[Math.min(t.retry_count || 0, 2)];
      const row = db.prepare(`
        SELECT 1 FROM tasks 
        WHERE id = ? 
          AND completed_at < datetime('now', '-${backoffMinutes} minutes')
      `).get(t.id);
      return !!row;
    });

    for (const task of readyToRetry) {
      console.log(`🔄 ${task.id}: ${task.title} (retry #${(task.retry_count || 0) + 1})`);
      await runAndComplete(task.id, task.title, task.description);
    }
  }
}
