// Engine escalation based on retry count
type Engine = 'glm' | 'opencode' | 'cursor';

function selectEngineWithFallback(
  preferredEngine: Engine,
  retryCount: number,
  cursorDailyCount: number,
  cursorLimit: number
): Engine {
  let engine = preferredEngine;

  // On retry, escalate to stronger engines
  if (engine === 'glm' && retryCount === 1) {
    engine = 'opencode';
    console.log(`[fallback] GLM → OpenCode (retry #${retryCount})`);
  } else if (engine === 'glm' && retryCount >= 2) {
    engine = 'cursor';
    console.log(`[fallback] GLM → Cursor (retry #${retryCount})`);
  } else if (engine === 'opencode' && retryCount >= 2) {
    engine = 'cursor';
    console.log(`[fallback] OpenCode → Cursor (retry #${retryCount})`);
  }

  // Check rate limits and downgrade if needed
  if (engine === 'cursor' && cursorDailyCount >= cursorLimit) {
    engine = 'opencode';
    console.log(`[fallback] Cursor daily limit reached → OpenCode`);
  }

  return engine;
}

// Usage
async function executeWithFallback(taskId: string, prompt: string): Promise<boolean> {
