### 2.3 Multi-Provider Router with Circuit Breaker

```typescript
interface LLMProvider {
  name: string;
  execute: (prompt: string) => Promise<string>;
  isHealthy: boolean;
  failureCount: number;
}

class LLMRouter {
  private providers: LLMProvider[] = [];
  private circuitBreakers = new Map<string, CircuitBreaker>();

  addProvider(provider: LLMProvider): void {
    this.providers.push(provider);
    this.circuitBreakers.set(
      provider.name,
      new CircuitBreaker({ failureThreshold: 3, resetTimeoutMs: 60000 }, provider.name)
    );
  }

  async route(prompt: string): Promise<string> {
    // Sort by health (healthy first), then by priority
    const sortedProviders = [...this.providers].sort((a, b) => {
      if (a.isHealthy && !b.isHealthy) return -1;
      if (!a.isHealthy && b.isHealthy) return 1;
      return a.failureCount - b.failureCount;
    });

    let lastError: Error | null = null;

    for (const provider of sortedProviders) {
      const circuit = this.circuitBreakers.get(provider.name)!;

      try {
        const result = await circuit.execute(() => provider.execute(prompt));
        provider.failureCount = Math.max(0, provider.failureCount - 1);
        return result;
      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error));
        provider.failureCount++;

        if (isAuthError(error)) {
          // Don't retry auth errors on this provider
          provider.isHealthy = false;
        }
      }
    }

    throw new Error(`All providers exhausted. Last error: ${lastError?.message}`);
  }
}
```

