## 3. Idempotency Patterns

### 3.1 Safe-to-Retry Operations

```typescript
// Make operations idempotent with unique request IDs
interface IdempotentRequest {
  idempotencyKey: string;
  payload: unknown;
}

class IdempotentExecutor {
  private completedKeys = new Set<string>();
  private inProgress = new Map<string, Promise<unknown>>();

  async execute<T>(
    key: string,
    operation: () => Promise<T>
  ): Promise<T> {
    // Already completed? Return cached result
    if (this.completedKeys.has(key)) {
      console.log(`[idempotent] ${key} already completed`);
      throw new Error('Already completed'); // Or return cached result
    }

    // Already in progress? Deduplicate
    if (this.inProgress.has(key)) {
      console.log(`[idempotent] ${key} in progress, deduplicating`);
      return this.inProgress.get(key) as Promise<T>;
    }

    // Execute and track
    const promise = operation().finally(() => {
      this.inProgress.delete(key);
      this.completedKeys.add(key);
    });

    this.inProgress.set(key, promise);
    return promise;
  }
}

// Database-backed idempotency (from OpenClaw task-db.ts)
function createTask(db: Database, taskId: string, template: TaskTemplate): boolean {
  // INSERT OR IGNORE makes this idempotent
  const result = db.prepare(`
    INSERT OR IGNORE INTO tasks (id, title, description, type, status, priority)
    VALUES (?, ?, ?, ?, 'pending', ?)
  `).run(taskId, template.title, template.description, template.type, template.priority);

  return result.changes > 0;
}
```

