// Reclaim tasks stuck in 'doing' state for too long
function reclaimStuckTasks(db: Database): number {
  const stuckTimeoutMinutes = 10;

  const stuck = db.prepare(`
    SELECT id, title 
    FROM tasks 
    WHERE status = 'doing' 
      AND started_at < datetime('now', '-${stuckTimeoutMinutes} minutes')
  `).all() as any[];

  for (const task of stuck) {
    db.prepare(`
      UPDATE tasks 
      SET status = 'failed', 
          result = 'stuck >${stuckTimeoutMinutes}min', 
          completed_at = datetime('now')
      WHERE id = ?
    `).run(task.id);

