## 5. Error Classification

### 5.1 Retryable vs Non-Retryable

From agent-task-queue/src/index.ts:21-111:

```typescript
const NON_RETRYABLE_PATTERNS = [
  /auth.*error/i,
  /credential.*invalid/i,
  /unauthorized/i,
  /too.*similar/i,      // Content duplication
  /QC failed/i,         // Quality check failed
];

const RETRYABLE_NETWORK_PATTERNS = [
  /ECONNRESET/,
  /ETIMEDOUT/,
  /ENOTFOUND/,
  /ECONNREFUSED/,
  /timeout/i,
  /rate.*limit/i,
];

class ErrorClassifier {
  isNonRetryable(result: string): boolean {
    return NON_RETRYABLE_PATTERNS.some(p => p.test(result));
  }

  isRetryableNetworkError(error: unknown): boolean {
    if (!(error instanceof Error)) return false;
    return RETRYABLE_NETWORK_PATTERNS.some(p => p.test(error.message));
  }

  isAuthError(result: string): boolean {
    return /auth|credential|unauthorized|token|api.*key/i.test(result);
  }

  classify(result: string, error?: Error): {
    status: 'completed' | 'failed' | 'suspended';
    shouldRetry: boolean;
    finalRetryCount: number;
  } {
    // Auth errors → suspend (needs manual intervention)
    if (this.isAuthError(result)) {
      return { status: 'suspended', shouldRetry: false, finalRetryCount: 99 };
    }

    // Non-retryable logic errors → fail immediately
    if (this.isNonRetryable(result)) {
      return { status: 'failed', shouldRetry: false, finalRetryCount: 99 };
    }

    // Network errors → retry
    if (error && this.isRetryableNetworkError(error)) {
      return { status: 'failed', shouldRetry: true, finalRetryCount: 0 };
    }

    // Default: retry with backoff
    return { status: 'failed', shouldRetry: true, finalRetryCount: 0 };
  }
}
```

### 5.2 Error Categories with Actions

