function categorizeError(result: string): ErrorAction {
  const lower = result.toLowerCase();

  if (/auth|credential|unauthorized|token|api.*key/.test(lower)) {
    return {
      category: 'auth_or_credential',
      suggestion: 'Check API credentials and environment variables',
      autoAction: () => suspendTask('auth_error'),
