    const review = await llmQualityReview(content, title);
    if (review.score < 6 && engine !== 'cursor') {
      // Keep for EVOLVE iteration
      completeTask(taskId, result.summary, true);
    } else if (review.score < 6) {
      // Even cursor failed QC
      completeTask(taskId, `LLM review ${review.score}/10: ${review.feedback}`, false);
    }
  }

