// Complete fallback chain from weakest to strongest model
async function executeWithFullFallback(
  taskId: string,
  prompt: string,
  maxRetries: number = 3
): Promise<{ ok: boolean; summary: string }> {
  const engines: Engine[] = ['glm', 'opencode', 'cursor'];
  let lastError: Error | null = null;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    const engineIndex = Math.min(attempt, engines.length - 1);
    const engine = engines[engineIndex];

    try {
      console.log(`[${taskId}] Attempt ${attempt + 1}/${maxRetries} using ${engine}`);
      const result = await executeWithEngine(engine, taskId, prompt);

      if (result.ok) {
        return result;
      }

      // Failed but didn't throw - check if retryable
      if (isNonRetryable(result.summary)) {
        return result; // Don't retry non-retryable errors
      }
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      // Wait before retry (exponential backoff)
      if (attempt < maxRetries - 1) {
        const delay = Math.pow(2, attempt) * 1000;
        await sleep(delay);
      }
    }
  }

  return {
    ok: false,
    summary: `All ${maxRetries} attempts failed. Last error: ${lastError?.message}`,
  };
}
