The custom error boundary class is a bit more verbose but offers the same level of performance as the other approaches.

### Error Boundary Decorator

Using TypeScript decorators to wrap components with error handling logic is a concise and clean approach. Here is an example:

```typescript
import React from 'react';

function errorBoundary<T extends React.ComponentType<any>>(WrappedComponent: T) {
  return class ErrorBoundaryComponent extends React.Component<React.ComponentProps<T>> {
    constructor(props: React.ComponentProps<T>) {
      super(props);
      this.state = { hasError: false };
    }

    static getDerivedStateFromError(error: Error): { hasError: boolean } {
      return { hasError: true };
    }

    componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
      console.error('ErrorBoundaryDecorator caught an error', error, errorInfo);
    }

    render() {
      const { hasError } = this.state;
      const { ...props } = this.props;

      return hasError ? (
        <div>
          <h1>Something went wrong.</h1>
          {/* Additional error information */}
        </div>
      ) : (
        <WrappedComponent {...props} />
      );
    }
  } as React.ComponentType<React.ComponentProps<T>>;
}

const MyComponent = () => {
  throw new Error('I crashed!');
};

const App = () => (
  <errorBoundary fallbackComponent={<h1>Something went wrong.</h1>}>
    <MyComponent />
  </errorBoundary>
);
```

The Error Boundary Decorator approach is concise and has minimal performance overhead.

