### TypeScript Interface

```typescript
interface StateOperation<T = unknown> {
  operation: 'read' | 'write' | 'delete' | 'compareAndSet';
  key: string;
  value?: T;
  expectedVersion?: number;
  agentId: string;
  timestamp: string;
}

interface StateRecord<T = unknown> {
  key: string;
  value: T;
  version: number;
  updatedBy: string;
  updatedAt: string;
}

interface StateClient {
  read<T>(key: string): Promise<StateRecord<T> | null>;
  write<T>(key: string, value: T, agentId: string): Promise<StateRecord<T>>;
  delete(key: string, agentId: string): Promise<void>;
  compareAndSet<T>(key: string, expected: T, desired: T, agentId: string): Promise<boolean>;
  watch(key: string, callback: (record: StateRecord) => void): () => void;
}
```

### Example Implementation

```typescript
import { randomUUID } from 'crypto';

class SharedStateClient implements StateClient {
  private store = new Map<string, StateRecord>();
  private watchers = new Map<string, Set<(record: StateRecord) => void>>();

  async read<T>(key: string): Promise<StateRecord<T> | null> {
    return this.store.get(key) || null;
  }

  async write<T>(key: string, value: T, agentId: string): Promise<StateRecord<T>> {
    const existing = this.store.get(key);
    const record: StateRecord<T> = {
      key,
      value,
      version: (existing?.version || 0) + 1,
      updatedBy: agentId,
      updatedAt: new Date().toISOString()
    };

    this.store.set(key, record);
    this.notifyWatchers(key, record);

    return record;
  }

  async delete(key: string, agentId: string): Promise<void> {
    this.store.delete(key);
  }

  async compareAndSet<T>(
    key: string,
    expected: T,
    desired: T,
    agentId: string
  ): Promise<boolean> {
    const existing = this.store.get(key);

    if (!existing || JSON.stringify(existing.value) !== JSON.stringify(expected)) {
      return false;
    }

    const record: StateRecord<T> = {
      key,
      value: desired,
      version: existing.version + 1,
      updatedBy: agentId,
      updatedAt: new Date().toISOString()
    };

    this.store.set(key, record);
    this.notifyWatchers(key, record);

    return true;
  }

  watch(key: string, callback: (record: StateRecord) => void): () => void {
    if (!this.watchers.has(key)) {
      this.watchers.set(key, new Set());
    }
    this.watchers.get(key)!.add(callback);

    return () => {
      this.watchers.get(key)?.delete(callback);
    };
  }

  private notifyWatchers(key: string, record: StateRecord): void {
    const watchers = this.watchers.get(key);
    if (watchers) {
      watchers.forEach(cb => cb(record));
    }
  }
}

// Usage: Distributed task queue with shared state
const state = new SharedStateClient();

async function claimTask(agentId: string, taskId: string): Promise<boolean> {
  const key = `task:${taskId}`;
  const task = await state.read<{ status: string; assignee: string | null }>(key);

  if (!task || task.value.status !== 'pending') {
    return false;
  }

  return state.compareAndSet(
    key,
    { status: 'pending', assignee: null },
    { status: 'claimed', assignee: agentId },
    agentId
  );
}
```

